using namespace std;

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    vector<pair<long long, int>> events(2 * n);
    for (int i = 0; i < n; i++) { long long s; scanf("%lld", &s); events[i] = {s, 1}; }
    for (int i = 0; i < n; i++) { long long e; scanf("%lld", &e); events[n + i] = {e, -1}; }
    // Half-open [S, E): at equal times the departure (-1) sorts before the arrival (+1).
    sort(events.begin(), events.end());
    int occupied = 0, answer = 0;
    for (auto &ev : events) {
        occupied += ev.second;
        answer = max(answer, occupied);
    }
    printf("%d\n", answer);
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.nextToken();
        int n = (int) st.nval;
        // Event = time * 2 + (1 for an arrival, 0 for a departure), so at equal times
        // the departure sorts first (half-open [S, E)).
        long[] events = new long[2 * n];
        for (int i = 0; i < n; i++) { st.nextToken(); events[i] = (long) st.nval * 2 + 1; }
        for (int i = 0; i < n; i++) { st.nextToken(); events[n + i] = (long) st.nval * 2; }
        Arrays.sort(events);
        int occupied = 0, answer = 0;
        for (long e : events) {
            occupied += (e & 1) == 1 ? 1 : -1;
            answer = Math.max(answer, occupied);
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	nextInt := func() int { sc.Scan(); v, _ := strconv.Atoi(sc.Text()); return v }
	n := nextInt()
	events := make([][2]int, 0, 2*n)
	for i := 0; i < n; i++ {
		events = append(events, [2]int{nextInt(), 1})
	}
	for i := 0; i < n; i++ {
		events = append(events, [2]int{nextInt(), -1})
	}
	// Half-open [S, E): at equal times the departure (-1) sorts before the arrival (+1).
	sort.Slice(events, func(i, j int) bool {
		if events[i][0] != events[j][0] {
			return events[i][0] < events[j][0]
		}
		return events[i][1] < events[j][1]
	})
	occupied, answer := 0, 0
	for _, ev := range events {
		occupied += ev[1]
		answer = max(answer, occupied)
	}
	fmt.Println(answer)
}
